import { ObstacleCategory, ObstacleType } from '../@types/obstacles.types';
import { ObstacleTypeUrlPart } from '../@types/obstacles.url.types';

export const obstacleTypeNameResource: Record<ObstacleType, string> = {
  [ObstacleType.Pass]: 'Перевал',
  [ObstacleType.Peak]: 'Вершина',
  [ObstacleType.Poi]: 'Точка интереса (POI)',
};

export const obstacleTypeNameGenitiveResource: Record<ObstacleType, string> = {
  [ObstacleType.Pass]: 'Перевал',
  [ObstacleType.Peak]: 'Вершину',
  [ObstacleType.Poi]: 'Точку интереса (POI)',
};

export const obstacleTypeNamePrepositionalResource: Record<ObstacleType, string> = {
  [ObstacleType.Pass]: 'Перевале',
  [ObstacleType.Peak]: 'Вершине',
  [ObstacleType.Poi]: 'Точке интереса (POI)',
};

export const getObstacleTypeName = (
  type: ObstacleType,
  variant: 'nominative' | 'genitive' | 'prepositional' = 'nominative',
) => {
  switch (variant) {
    case 'nominative':
      return obstacleTypeNameResource[type];
    case 'genitive':
      return obstacleTypeNameGenitiveResource[type];
    case 'prepositional':
      return obstacleTypeNamePrepositionalResource[type];
  }
};

